insert into public.practica_claves (deck, lamina, pregunta, tipo, clave, modelo) values
  ('formacion-ajedrez/practica-01', 1, 'p1', 'opciones', '{"correcta":"mate"}'::jsonb, 'Jaque mate: el rey está en jaque y no tiene ninguna jugada legal. La partida terminó (art. 5.1).'),
  ('formacion-ajedrez/practica-01', 1, 'p2', 'opciones', '{"correcta":"ahogado"}'::jsonb, 'Ahogado: el rey no está en jaque y el bando que mueve no tiene ninguna jugada legal. Tablas (art. 5.2.1).'),
  ('formacion-ajedrez/practica-01', 1, 'p3', 'opciones', '{"correcta":"jaque"}'::jsonb, 'Jaque, pero no mate: el rey tiene al menos una jugada legal para salir del jaque. La partida sigue (art. 3.9).'),
  ('formacion-ajedrez/practica-01', 1, 'p4', 'opciones', '{"correcta":"muerta"}'::jsonb, 'Posición muerta: ninguna serie de jugadas legales puede terminar en mate. Tablas de inmediato, sin reclamo (art. 5.2.2).'),
  ('formacion-ajedrez/practica-01', 2, 'p5', 'opciones', '{"correcta":"mate"}'::jsonb, 'Jaque mate: el rey está en jaque y no tiene ninguna jugada legal. La partida terminó (art. 5.1).'),
  ('formacion-ajedrez/practica-01', 2, 'p6', 'opciones', '{"correcta":"muerta"}'::jsonb, 'Posición muerta: ninguna serie de jugadas legales puede terminar en mate. Tablas de inmediato, sin reclamo (art. 5.2.2).'),
  ('formacion-ajedrez/practica-01', 2, 'p7', 'opciones', '{"correcta":"sigue"}'::jsonb, 'No hay jaque y sí hay material para dar mate: la partida sigue.'),
  ('formacion-ajedrez/practica-01', 2, 'p8', 'opciones', '{"correcta":"ahogado"}'::jsonb, 'Ahogado: el rey no está en jaque y el bando que mueve no tiene ninguna jugada legal. Tablas (art. 5.2.1).'),
  ('formacion-ajedrez/practica-01', 3, 'planilla', 'planilla', '["e4","e5","Cf3","d6","Ac4","Ag4","Cc3","g6","Cxe5","Axd1","Axf7+","Re7","Cd5#"]'::jsonb, 'La partida dictada: 1. e4 e5 2. Cf3 d6 3. Ac4 Ag4 4. Cc3 g6 5. Cxe5 Axd1 6. Axf7+ Re7 7. Cd5#'),
  ('formacion-ajedrez/practica-01', 4, 'decision', 'texto', null, 'Pieza tocada: debe mover el alfil si tiene una jugada legal (art. 4.3).'),
  ('formacion-ajedrez/practica-01', 5, 'decision', 'texto', null, 'Jugada ilegal: se vuelve a la posición anterior, juega con la pieza que tocó si tiene jugada legal y su rival recibe 2 minutos (art. 7.5).'),
  ('formacion-ajedrez/practica-01', 6, 'decision', 'texto', null, 'Pieza tocada: «compongo» solo vale en su turno y avisando antes de tocar la pieza (art. 4.2.1).'),
  ('formacion-ajedrez/practica-01', 7, 'decision', 'texto', null, 'Aplica pieza tocada: como tocó primero la torre, debe mover esa torre y no puede enrocar con ella. El enroque se hace tocando primero el rey. (Leyes del Ajedrez 2023 (Handbook E.I.01), art. 4.4.2)'),
  ('formacion-ajedrez/practica-01', 8, 'decision', 'texto', null, 'Es una jugada ilegal completada: el cambio del peón es parte de la misma jugada. No se repone la posición: el peón se cambia por una dama del mismo color y se aplica la sanción de la primera jugada ilegal (dos minutos más para el rival en ritmo clásico, uno en rápidas y relámpago). (Leyes del Ajedrez 2023 (Handbook E.I.01), art. 3.7.5, 7.5.2 y 7.5.5)'),
  ('formacion-ajedrez/practica-01', 9, 'decision', 'texto', null, 'La partida terminó en tablas en el momento en que se llegó a esa posición: es posición muerta y no hace falta ningún reclamo. (Leyes del Ajedrez 2023 (Handbook E.I.01), art. 5.2.2)'),
  ('formacion-ajedrez/practica-01', 10, 'decision', 'texto', null, 'Es una jugada ilegal: el derecho a capturar al paso solo existe en la respuesta inmediata al avance doble. (Leyes del Ajedrez 2023 (Handbook E.I.01), art. 3.7.4.1 y 7.5)'),
  ('formacion-ajedrez/clase-02', 25, 'respuesta', 'texto', null, 'La jugada no estaba completada: se corrige sin sanción, pero con la pieza que tocó, si tiene una jugada legal (pieza tocada). No puede cambiar de pieza. Art. 4.3 y 7.5.1.'),
  ('formacion-ajedrez/clase-02', 26, 'respuesta', 'texto', null, 'Tablas: la segunda ilegal hace perder, salvo que el rival no pueda dar mate por ninguna serie de jugadas legales. Art. 7.5.5.'),
  ('formacion-ajedrez/clase-02', 27, 'respuesta', 'texto', null, 'Es una molestia al rival: primero una advertencia y, si sigue, una sanción mayor del art. 12.9. Art. 11.5 y 12.9.'),
  ('formacion-ajedrez/clase-02', 28, 'respuesta', 'texto', null, 'Incumplió la condición de tenerlo completamente apagado, así que se aplica la sanción prevista por el reglamento o, si no prevé otra, la pérdida de la partida. Art. 11.3.2.'),
  ('formacion-ajedrez/clase-02', 29, 'respuesta', 'texto', null, 'Como ya hicieron 10 o más jugadas cada uno, la partida sigue con los colores que se jugaron. Art. 7.3.'),
  ('formacion-ajedrez/clase-02', 30, 'respuesta', 'texto', null, 'Sí: firmar no quita el derecho a apelar. Los plazos y la forma los fija el reglamento del torneo. Art. 8.7 y 11.10.'),
  ('formacion-ajedrez/clase-03', 42, 'respuesta', 'texto', null, 'a) 10 minutos: relámpago (10 o menos). b) 10 + 5 = 15: rápidas. c) 25 + 10 = 35: rápidas. d) 60: clásico.'),
  ('formacion-ajedrez/clase-03', 43, 'respuesta', 'texto', null, 'A: venció a C (3), D (2½) y F (1) = 6½, más la mitad de B (3½) = 1¾. Total 8¼. B: venció a D (2½), E (1½) y F (1) = 5, más la mitad de A = 1¾. Total 6¾. Queda primero A. (El encuentro directo no los separaba: empataron entre sí.)'),
  ('formacion-ajedrez/clase-03', 44, 'respuesta', 'texto', null, 'Carla: Buchholz 12½; corte 1 (se quita ½) = 12. Diego: Buchholz 13; corte 1 (se quita 1) = 12. Si el primer desempate es Buchholz, gana Diego; si fuera Buchholz con corte 1, siguen empatados y se pasa al siguiente criterio.'),
  ('formacion-ajedrez/clase-03', 45, 'respuesta', 'texto', null, 'Suizo de al menos cinco rondas, con un ritmo mínimo de 10 min + 2 s (66.2.a); al menos dos frente al tablero (66.2.f); la persona árbitra principal, en el congresillo, con al menos tres criterios (66.4); hasta que su reloj caiga a cero (art. 30).'),
  ('formacion-ajedrez/clase-03', 46, 'respuesta', 'texto', null, 'La Normativa prevé suizo con más de siete y todos contra todos con seis o menos (66.2.d y 66.2.e): no dice nada para exactamente siete. La persona árbitra principal lo plantea en el congresillo y deja el acuerdo escrito en el acta, que obliga a todas las delegaciones (art. 34).'),
  ('formacion-ajedrez/clase-03', 47, 'respuesta', 'texto', null, '1–7, 8–2, 3–9, 10–4, 5–11, 12–6 (el primero de cada pareja lleva blancas).'),
  ('formacion-ajedrez/clase-03', 48, 'respuesta', 'texto', null, '10 jugadores: 9 rondas y 45 partidas. 9 jugadores: se agrega un descanso, 9 rondas y 36 partidas, con un jugador libre por ronda.'),
  ('formacion-ajedrez/clase-03', 49, 'respuesta', 'texto', null, 'Ronda 1: 1–4, 2–3. Ronda 2: 4–3, 1–2. Ronda 3: 2–4, 3–1 (el primero de cada pareja lleva blancas).'),
  ('formacion-ajedrez/clase-03', 50, 'respuesta', 'texto', null, 'Un jugador queda libre (bye) y recibe un punto sin color. No puede recibirlo quien ya lo tuvo ni quien ya ganó por incomparecencia.'),
  ('formacion-ajedrez/clase-04', 19, 'respuesta', 'texto', null, 'Tiempo base 90:00 e incremento de 30 s por jugada, en ambos lados. Sí: con incremento de 30 segundos o más no se puede dejar de anotar (art. 8.4).'),
  ('formacion-ajedrez/clase-04', 20, 'respuesta', 'texto', null, 'Tiempo base 15:00 e incremento de 10 s. 15 + 10 = 25 minutos: rápidas.'),
  ('formacion-ajedrez/clase-04', 21, 'respuesta', 'texto', null, 'Tiempo base 3:00 e incremento de 2 s. 3 + 2 = 5 minutos: relámpago.'),
  ('formacion-ajedrez/clase-04', 22, 'respuesta', 'texto', null, 'Tablas: el rival no puede dar mate por ninguna serie de jugadas legales (art. 6.9).'),
  ('formacion-ajedrez/clase-04', 23, 'respuesta', 'texto', null, 'El tiempo de incomparecencia es cero: pierde, salvo que el árbitro decida otra cosa en ese caso puntual (art. 6.7).'),
  ('formacion-ajedrez/clase-05', 18, 'respuesta', 'texto', null, 'Hechos: suena el celular del jugador X en la mesa N, ronda R, a tal hora. Artículo: 11.3.2 y el reglamento del torneo. Decisión: pérdida de la partida (o la sanción menor que prevea el reglamento), comunicada a las dos partes. Registro: «Ronda R, mesa N: suena el celular del jugador X durante la partida; se aplica el art. 11.3.2 y se declara la partida perdida. Firma del árbitro».'),
  ('formacion-ajedrez/clase-05', 19, 'respuesta', 'texto', null, '20 tableros y 20 juegos de piezas completos, más 2 o 3 de repuesto; 20 relojes configurados, más 2 o 3 de repuesto; planillas para cada ronda; actas de resultados; formularios de inscripción; lista de cotejo; numeración de mesas; hojas de emparejamiento y tabla para publicar.'),
  ('formacion-ajedrez/clase-05', 20, 'respuesta', 'texto', null, 'Nadie puede comentar ni interferir en una partida en curso. Se retira al familiar de la zona de juego y se evalúa si hubo ayuda: si la hubo, se sanciona a la jugadora según el art. 12.9. Se registra la incidencia (art. 11.3.1 y 12.7).'),
  ('formacion-ajedrez/clase-06', 18, 'respuesta', 'texto', null, '«Resuelve los reclamos siguiendo el procedimiento»: Sí. «Documenta cada incidencia en la planilla o en el acta»: No, con una observación concreta (qué incidencia faltó registrar).'),
  ('formacion-ajedrez/clase-06', 19, 'respuesta', 'texto', null, 'Por ejemplo: «La decisión tuvo base en el art. 12.9, pero la sanción no fue proporcionada: para una primera falta leve correspondía una advertencia. Te sugiero empezar por la sanción más baja de la lista y subir si la falta se repite».')
